  rainGeo.setAttribute('position',new T.BufferAttribute(rainPos,3));const rain=new T.LineSegments(rainGeo,own(new T.LineBasicMaterial({color:'#d6e2ee',transparent:true,opacity:.5,depthWrite:false})));rain.frustumCulled=false;rain.visible=false;scene.add(rain);
  const snowPos=new Float32Array(SNOW*3),snowGeo=own(new T.BufferGeometry());for(let i=0;i<SNOW;i++)snowPos.set([(Math.random()*2-1)*BOX,Math.random()*TOP*2-TOP*.5,(Math.random()*2-1)*BOX],i*3);
  snowGeo.setAttribute('position',new T.BufferAttribute(snowPos,3));const snow=new T.Points(snowGeo,own(new T.PointsMaterial({color:'#ffffff',size:.3,map:dot,transparent:true,opacity:.95,depthWrite:false})));snow.frustumCulled=false;snow.visible=false;scene.add(snow);

  // Fireflies on clear warm nights, low around the player.
  const FLIES=simple?0:46,flyPos=new Float32Array(FLIES*3),flySeed=[];for(let i=0;i<FLIES;i++){flySeed.push({a:Math.random()*6.3,r:3+Math.random()*16,h:.5+Math.random()*2,s:.2+Math.random()*.5});}
  const flyGeo=own(new T.BufferGeometry());flyGeo.setAttribute('position',new T.BufferAttribute(flyPos,3));const fireflies=new T.Points(flyGeo,own(new T.PointsMaterial({color:'#efff9a',size:.34,map:dot,transparent:true,opacity:0,depthWrite:false,blending:T.AdditiveBlending,fog:false})));fireflies.frustumCulled=false;scene.add(fireflies);

