    const colors=['#5b7fe0','#7d5bd6','#d96bb5','#4aa3e0','#9b6be0'];glorySpots.forEach((s,i)=>{gloryData.push(s);glories.setColorAt(i,new T.Color(colors[i%colors.length]));});
