    glorySpots.forEach((s,i)=>{for(let j=0;j<3;j++){const a=s.rot+j*2.1+i;le.set(.4,a,.3);lq.setFromEuler(le);lp.set(s.x+Math.cos(a)*.14,s.y-.06-j*.07,s.z+Math.sin(a)*.14);ls.set(1.3,.45,1);lm.compose(lp,lq,ls);gleaves.setMatrixAt(n++,lm);}});
