      for(let i=0;i<RAIN;i++){const o=i*6;rainPos[o+1]-=fall;rainPos[o+4]-=fall;rainPos[o]+=dx;rainPos[o+3]+=dx;rainPos[o+2]+=dz;rainPos[o+5]+=dz;
        if(rainPos[o+1]<-TOP*.5){const px=(Math.random()*2-1)*BOX,py=TOP+Math.random()*4,pz=(Math.random()*2-1)*BOX;rainPos.set([px,py,pz,px-fx.windX*.25,py-.8,pz-fx.windZ*.25],o);}}
