// v111 water (Yoshi: "make the game beautiful"): patches a MeshStandardMaterial so its surface ripples in world space
// (three swell directions bend the normal, so the sun glints move), gets a sky-blue sheen at grazing angles and tiny
// sun sparkles by day. WATER_TIME is shared; world.js sets it every frame. Cheap: a few sines per pixel, no textures.
export const WATER_TIME={value:0},WATER_NIGHT={value:0};
